<script lang="ts">import {page} from '$app/stores';import {enhance} from '$app/forms';import type {PageData,ActionData} from './$types';import Icon from '$lib/components/Icon.svelte';export let data:PageData;export let form:ActionData;let title=data.project?.title||'';let summary=data.project?.summary||'';let cover=data.project?.coverMediaId||data.project?.coverUrl||'/demo/ritmo.webp';let slug=data.project?.slug||'';let description=data.project?.description||'';let coverAlt=data.project?.coverAlt||'';let videoUrl=data.project?.videoUrl||'';let sourceUrl=data.project?.sourceUrl||'';let categoryId=data.project?.categoryId||'';let status=data.project?.status||'draft';let sortOrder=data.project?.sortOrder||0;let featured=data.project?.featured||false;$:image=cover.startsWith('/')?cover:data.media.find(m=>m.id===cover)?.url||'/demo/ritmo.webp';let saving=false;</script>
<svelte:head><title>{data.project?'Editar trabalho':'Novo trabalho'} — FRAME</title></svelte:head><div class="admin-heading"><div><a class="text-link" href="/admin/trabalhos" style="font-size:11px;margin-bottom:16px">Voltar aos trabalhos</a><h1>{data.project?'Editar trabalho':'Novo trabalho'}</h1><p>{data.project?'Refine os detalhes e decida quando mostrar.':'Comece como rascunho e publique quando fizer sentido.'}</p></div></div>{#if form?.error}<div class="alert" role="alert">{form.error}</div>{:else if $page.url.searchParams.has('salvo')}<div class="alert success" role="status">Trabalho salvo.</div>{/if}<div class="editor-layout"><form method="POST" use:enhance={()=>{saving=true;return async({update})=>{try{await update();}finally{saving=false;}};}}><section class="panel"><div class="panel-title"><h2>A história do trabalho</h2></div><div class="form-grid"><div class="field full"><label for="title">Título</label><input id="title" name="title" bind:value={title} required maxlength="160"/></div><div class="field full"><label for="slug">Endereço do trabalho</label><input id="slug" name="slug" bind:value={slug} required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="120" placeholder="nome-do-trabalho"/><small>Letras minúsculas, números e hífens. Exemplo: entre-planos.</small></div><div class="field full"><label for="summary">Resumo</label><textarea id="summary" name="summary" bind:value={summary} maxlength="500" rows="2" style="min-height:80px"></textarea></div><div class="field full"><label for="description">Contexto e créditos</label><textarea id="description" name="description" bind:value={description} rows="6" maxlength="10000"></textarea><small>Descreva o contexto, seu papel e os autores envolvidos.</small></div></div></section><section class="panel"><div class="panel-title"><h2>Imagem e vídeo</h2></div><div class="form-grid"><div class="field full"><label for="cover">Capa</label><select id="cover" name="cover" bind:value={cover}><optgroup label="Capas demonstrativas"><option value="/demo/ritmo.webp">Entre planos</option><option value="/demo/orbita.webp">Cena em construção</option><option value="/demo/fragmentos.webp">Luz de ensaio</option><option value="/demo/entre-planos.webp">Fora de quadro</option></optgroup><optgroup label="Sua biblioteca">{#each data.media as media}<option value={media.id}>{media.alt||media.filename}</option>{/each}</optgroup></select><small><a href="/admin/midia" style="text-decoration:underline">Adicione suas próprias capas na biblioteca.</a></small></div><div class="field full"><label for="coverAlt">Descrição acessível da capa</label><input id="coverAlt" name="coverAlt" bind:value={coverAlt} maxlength="300"/></div><div class="field full"><label for="videoUrl">Link do vídeo</label><input id="videoUrl" name="videoUrl" type="url" bind:value={videoUrl} placeholder="https://vimeo.com/..." maxlength="500"/><small>YouTube ou Vimeo. Não cole código de incorporação.</small></div><div class="field full"><label for="sourceUrl">Publicação original</label><input id="sourceUrl" name="sourceUrl" type="url" bind:value={sourceUrl} placeholder="https://x.com/.../status/..." maxlength="2048"/><small>Opcional. URL HTTPS sem credenciais. Abre como referência externa; não incorpora vídeo.</small></div></div></section><section class="panel"><div class="panel-title"><h2>Como apresentar</h2></div><div class="form-grid"><div class="field"><label for="categoryId">Categoria</label><select id="categoryId" name="categoryId" bind:value={categoryId}><option value="">Sem categoria</option>{#each data.categories as c}<option value={c.id}>{c.name}</option>{/each}</select></div><div class="field"><label for="status">Visibilidade</label><select id="status" name="status" bind:value={status}><option value="draft">Rascunho privado</option><option value="published">Publicado</option></select></div><div class="field"><label for="sortOrder">Ordem na coleção</label><input id="sortOrder" name="sortOrder" type="number" min="0" max="10000" bind:value={sortOrder}/></div><div class="field" style="justify-content:center"><label style="display:flex;align-items:center;gap:10px"><input name="featured" type="checkbox" bind:checked={featured} style="width:17px;min-height:17px"/> Destacar este trabalho</label></div></div></section><div class="form-actions"><button class="btn accent" disabled={saving}>{saving?'Salvando…':'Salvar trabalho'} <Icon name="check" size={16}/></button><a href="/admin/trabalhos" class="btn secondary">Voltar</a></div></form><aside class="editor-preview panel"><div class="panel-title"><h2>Um primeiro olhar</h2></div><img src={image} alt="Prévia da capa selecionada"/><h3>{title||'O título da sua ideia'}</h3><p>{summary||'O resumo do trabalho aparece aqui.'}</p><p class="fineprint" style="margin-top:25px">Esta prévia acompanha os campos de título, resumo e capa. Salve para aplicar as alterações ao portfólio.</p>{#if data.project?.status==='published'}<a class="text-link" href={`/trabalhos/${data.project.slug}`} target="_blank" rel="noopener" style="margin-top:25px">Abrir trabalho publicado <Icon name="diagonal" size={14}/></a>{/if}</aside></div>
